interface MonsterType {
  readonly id: string;
  readonly baseHealth: number;
  readonly attack: string;
}

const TYPES = [
  { id: "troll",  baseHealth: 48,  attack: "The troll clubs you!" },
  { id: "dragon", baseHealth: 230, attack: "The dragon breathes fire!" },
] as const satisfies readonly MonsterType[];

const registry: ReadonlyMap<string, MonsterType> = new Map(TYPES.map(t => [t.id, t]));
